-- Each verb's distinct meanings in the Qurʾān (paradigm_json.quran_meanings: en, how many uses, example āyāt), read from
-- every finite use of the verb and how the translations render it there (Saheeh International, checked against Haleem,
-- Asad, Pickthall and Mahmoud K's verbatim where a use looked different) — owner, 2026-10-16: "meaning also all unique in
-- Qurʾān · check translations also". Where the translations do not show our one-line meaning, it is corrected: نَزَّلَ and
-- تَنَزَّلَ carry no "in stages / little by little" in the verb itself (only where تَنْزِيلًا follows: 17:106, 25:32);
-- قَبِلَ never means "receive"; عَقَّبَ "overturn" is the participle مُعَقِّب (13:41), not the verb; صَارَ's one use
-- (42:53) is "return to". تَقَابَلَ and اسْتَقْبَلَ have no finite use — only مُتَقَابِلِين (15:47 …) and مُسْتَقْبِل (46:24).
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to come down, to descend", "n": 4, "ayat": ["34:2", "57:4", "57:16"]}, {"en": "to bring down (come down with it, nazala bi-)", "n": 1, "ayat": ["26:193"]}, {"en": "to land on a place (punishment striking a people)", "n": 1, "ayat": ["37:177"]}]'), '$.quran_meanings_note', '17:105 (the truth ''has descended'') is plain ''come down''. 37:177: Saheeh/Haleem ''descends on their yard'', Asad ''alights upon them'', Pickthall ''cometh home to them'' - the alighting/befalling sense; the only finite trace of ''arrive and stay''.') WHERE id = 'PAR:نزل:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to send down, to reveal", "n": 62, "ayat": ["2:23", "15:9", "43:11"]}]'), '$.quran_meanings_note', 'Translations show no ''in stages / again and again'' in the verb itself: Book, rain, angels, manna, a sign, authority - all simply ''sent down'' (Gabriel ''brought it down'' 2:97, 16:102). ''Progressively'' / ''in successive descent'' appears only where the masdar tanzīlan follows (17:106, 25:25, 76:23), and 25:32 contrasts it with ''all at once''. Suggest the gloss ''to send down'' with the gradual sense flagged as coming from those contexts, not from every use.', '$.meaning', 'to send down') WHERE id = 'PAR:نزل:II';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to send down (revelation, rain, calm, angels)", "n": 179, "ayat": ["2:4", "2:22", "48:26"]}, {"en": "to give, to provide (clothing, cattle)", "n": 2, "ayat": ["7:26", "39:6"]}, {"en": "to bring someone down (from their forts)", "n": 1, "ayat": ["33:26"]}, {"en": "to let someone land and settle (at a place)", "n": 1, "ayat": ["23:29"]}]'), '$.quran_meanings_note', '57:25 iron and 10:59 provision stay under ''send down'' (Saheeh, Haleem, Pickthall all say sent down/revealed). 7:26 Saheeh ''bestowed'', Haleem ''given''; 39:6 Saheeh/Pickthall ''provided'', Haleem ''gave''. 23:29 ''let me land at a blessed landing place''.') WHERE id = 'PAR:نزل:IV';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to come down, to descend (angels, devils, command)", "n": 6, "ayat": ["97:4", "41:30", "26:221"]}, {"en": "to bring down (come down with it, tanazzala bi-)", "n": 1, "ayat": ["26:210"]}]'), '$.quran_meanings_note', 'No translation renders ''little by little''; all say ''descend''. The repeated/ongoing sense comes from the present tense (tatanazzalu, tanazzalu), not the gloss.', '$.meaning', 'to come down, to descend') WHERE id = 'PAR:نزل:V';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to forgive", "n": 65, "ayat": ["39:53", "28:16", "42:37"]}]'), '$.quran_meanings_note', '61 uses have God as forgiver; 4 have people forgiving people (42:37, 42:43, 45:14, 64:14). Translations render both ''forgive'', so not split.') WHERE id = 'PAR:غفر:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to ask (God) for forgiveness", "n": 22, "ayat": ["4:110", "11:3", "51:18"]}, {"en": "to ask forgiveness for someone else (istaghfara li-)", "n": 18, "ayat": ["9:80", "12:98", "63:6"]}]'), '$.quran_meanings_note', 'Split by li- + another person: praying on someone''s behalf (Prophet, Abraham, Jacob, angels). 47:19 (for your sin and for the believers) counted under the first.') WHERE id = 'PAR:غفر:X';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to accept", "n": 9, "ayat": ["3:85", "24:4", "42:25"]}]'), '$.quran_meanings_note', 'Intercession, ransom, repentance, spending, testimony - all ''accepted''. No ''receive'' sense in the translations (9:104 ''receives charities'' is a different verb, akhadha).', '$.meaning', 'to accept') WHERE id = 'PAR:قبل:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to come toward, to approach", "n": 5, "ayat": ["28:31", "37:94", "51:29"]}, {"en": "to turn to one another (aqbala ba''duhum ''ala ba''d)", "n": 4, "ayat": ["37:27", "52:25", "68:30"]}]'), '$.quran_meanings_note', '12:82 ''the caravan in which we came'' is under approach/come.') WHERE id = 'PAR:قبل:IV';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to accept (an offering, a prayer, a person)", "n": 10, "ayat": ["2:127", "5:27", "14:40"]}]'), '$.quran_meanings_note', '3:37 ''her Lord accepted her [Mary] with good acceptance'' is the same sense.') WHERE id = 'PAR:قبل:V';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings_note', 'No finite verb in the Qur''an. Only the participle mutaqābilīn, 4x (15:47, 37:44, 44:53, 56:16): ''facing one another'' (on couches in Paradise) - all translations agree.') WHERE id = 'PAR:قبل:VI';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings_note', 'No finite verb in the Qur''an. Only the participle mustaqbil, 1x (46:24): a cloud ''approaching / coming toward their valleys'' (Saheeh, Haleem, Asad, Pickthall). Supports ''to head for'', not ''to face''.', '$.meaning', 'to head for, to come toward') WHERE id = 'PAR:قبل:X';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to repent, to turn back to God", "n": 40, "ayat": ["11:3", "25:70", "66:8"]}, {"en": "of God: to accept repentance, to turn to in mercy", "n": 23, "ayat": ["2:37", "9:117", "73:20"]}]'), '$.quran_meanings_note', 'God sense = tāba ''alā (and 9:27 yatūbu Allāh). 9:118 has both: ''He turned to them so they could repent''.') WHERE id = 'PAR:توب:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to turn back, to look back", "n": 2, "ayat": ["27:10", "28:31"]}]'), '$.quran_meanings_note', 'Both: Moses fled ''and did not return / look back''. ''To overturn a ruling'' is not a finite use; it comes from the participle mu''aqqib (13:41).', '$.meaning', 'to turn back, to look back') WHERE id = 'PAR:عقب:II';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to punish in return, to hit back with the same", "n": 5, "ayat": ["16:126", "22:60"]}, {"en": "to get your turn (win back something in return)", "n": 1, "ayat": ["60:11"]}]'), '$.quran_meanings_note', '60:11: Saheeh ''you subsequently obtain [something]'', Pickthall ''ye have your turn (of triumph)'', Haleem ''acquires [gains] from them'' - not punishment. Passive ''uqibtum/''uqiba in 16:126, 22:60 = ''were harmed''.') WHERE id = 'PAR:عقب:III';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to make something follow as a result (as a penalty)", "n": 1, "ayat": ["9:77"]}]'), '$.quran_meanings_note', 'Saheeh ''penalized them with hypocrisy'', Pickthall ''made the consequence (to be) hypocrisy'', Haleem ''made hypocrisy settle''.') WHERE id = 'PAR:عقب:IV';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to be long, to last long (of time, life)", "n": 3, "ayat": ["20:86", "21:44", "57:16"]}]')) WHERE id = 'PAR:طول:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to grow long, to stretch on (of life, time)", "n": 1, "ayat": ["28:45"]}]')) WHERE id = 'PAR:طول:VI';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.quran_meanings', json('[{"en": "to return to, to end up with", "n": 1, "ayat": ["42:53"]}]'), '$.quran_meanings_note', 'Only finite use: ''to Allah all matters return'' (Haleem ''return'', Pickthall ''reach Allah at last'', Saheeh ''evolve''). ''To become'' is not shown in the Qur''an.', '$.meaning', 'to return to, to end up with') WHERE id = 'PAR:صير:I';
UPDATE kmaps_cache_version SET version = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family IN ('rest','books');
